    for mm in re.finditer(rb'beginbfchar(.*?)endbfchar', d, re.S):
        seg = mm.group(1)
        for p in re.finditer(rb'<([0-9A-Fa-f]{4})>\s*<([0-9A-Fa-f]{4,8})>', seg):
            src = int(p.group(1),16); hx = p.group(2).decode()
            cmap[src] = ''.join(chr(int(hx[i:i+4],16)) for i in range(0,len(hx),4))
    for mm in re.finditer(rb'beginbfrange(.*?)endbfrange', d, re.S):
        seg = mm.group(1)
        for p in re.finditer(rb'<([0-9A-Fa-f]{4})>\s*<([0-9A-Fa-f]{4})>\s*<([0-9A-Fa-f]{4})>', seg):
            lo,hi,base = int(p.group(1),16), int(p.group(2),16), int(p.group(3),16)
